func (s *APIService) UpdateUser(ctx context.Context, request *apipb.UpdateUserRequest) (*apipb.User, error) {
	if request.User == nil {
		return nil, status.Errorf(codes.InvalidArgument, "user is required")
	}
	if request.UpdateMask == nil || len(request.UpdateMask.Paths) == 0 {
		return nil, status.Errorf(codes.InvalidArgument, "update mask is empty")
	}
	user, err := ResolveUserByName(ctx, s.Store, request.User.Name)
	if err != nil {
		return nil, status.Errorf(codes.InvalidArgument, "invalid user name: %v", err)
	}
	if user == nil {
		if request.AllowMissing {
			return nil, status.Errorf(codes.NotFound, "user not found")
		}
		return nil, status.Errorf(codes.NotFound, "user not found")
	}
	userID := user.ID
	currentUser, err := s.fetchCurrentUser(ctx)
	if err != nil {
		return nil, status.Errorf(codes.Internal, "failed to get user: %v", err)
	}
	if currentUser == nil {
		return nil, status.Errorf(codes.Unauthenticated, "user not authenticated")
	}
	// Check permission.
	// Only allow admin or self to update user.
	if currentUser.ID != userID && currentUser.Role != store.RoleAdmin {
		return nil, status.Errorf(codes.PermissionDenied, "permission denied")
	}

	currentTsSec := time.Now().Unix()
	update := &store.UpdateUser{
		ID:        user.ID,
		UpdatedTs: &currentTsSec,
	}
	instanceGeneralSetting, err := s.Store.GetInstanceGeneralSetting(ctx)
	if err != nil {
		return nil, status.Errorf(codes.Internal, "failed to get instance general setting: %v", err)
	}
	passwordChanged := false
	for _, field := range request.UpdateMask.Paths {
		switch field {
		case "username":
			if instanceGeneralSetting.DisallowChangeUsername {
				return nil, status.Errorf(codes.PermissionDenied, "permission denied: disallow change username")
			}
			if err := validateWritableUsername(request.User.Username); err != nil {
				return nil, status.Errorf(codes.InvalidArgument, "%v", err)
			}
			update.Username = &request.User.Username
		case "display_name":
			if instanceGeneralSetting.DisallowChangeNickname {
				return nil, status.Errorf(codes.PermissionDenied, "permission denied: disallow change nickname")
			}
			update.Nickname = &request.User.DisplayName
		case "email":
			email, err := store.NormalizeEmail(request.User.Email)
			if err != nil {
				return nil, status.Errorf(codes.InvalidArgument, "%v", err)
			}
			update.Email = &email
		case "avatar_url":
			// Validate avatar MIME type to prevent XSS during upload
			if request.User.AvatarUrl != "" {
				if len(request.User.AvatarUrl) > maxAvatarDataURIBytes {
					return nil, status.Errorf(codes.InvalidArgument, "avatar exceeds the maximum size of %d bytes", maxAvatarImageBytes)
				}
				imageType, _, err := extractImageInfo(request.User.AvatarUrl)
				if err != nil {
					return nil, status.Errorf(codes.InvalidArgument, "invalid avatar format: %v", err)
				}
				// Only allow safe image formats for avatars
				allowedAvatarTypes := map[string]bool{
					"image/png":  true,
					"image/jpeg": true,
					"image/jpg":  true,
					"image/gif":  true,
					"image/webp": true,
				}
				if !allowedAvatarTypes[imageType] {
					return nil, status.Errorf(codes.InvalidArgument, "invalid avatar image type: %s. Only PNG, JPEG, GIF, and WebP are allowed", imageType)
				}
			}
			update.AvatarURL = &request.User.AvatarUrl
		case "description":
			update.Description = &request.User.Description
		case "role":
			// Only allow admin to update role.
			if currentUser.Role != store.RoleAdmin {
				return nil, status.Errorf(codes.PermissionDenied, "permission denied")
			}
			role := convertUserRoleToStore(request.User.Role)
			update.Role = &role
		case "password":
			if err := validatePassword(request.User.Password); err != nil {
				return nil, status.Errorf(codes.InvalidArgument, "%v", err)
			}
			passwordHash, err := bcrypt.GenerateFromPassword([]byte(request.User.Password), bcrypt.DefaultCost)
			if err != nil {
				return nil, status.Errorf(codes.Internal, "failed to generate password hash: %v", err)
			}
			passwordHashStr := string(passwordHash)
			update.PasswordHash = &passwordHashStr
			passwordChanged = true
		case "state":
			if currentUser.Role != store.RoleAdmin {
				return nil, status.Errorf(codes.PermissionDenied, "permission denied")
			}
			rowStatus := convertStateToStore(request.User.State)
			update.RowStatus = &rowStatus
		default:
			return nil, status.Errorf(codes.InvalidArgument, "invalid update path: %s", field)
		}
	}

	updatedUser, err := s.Store.UpdateUser(ctx, update)
	if err != nil {
		if stderrors.Is(err, store.ErrLastSpaceAdmin) {
			return nil, status.Error(codes.FailedPrecondition, "an active space must retain an active administrator")
		}
		if stderrors.Is(err, store.ErrLastInstanceAdmin) {
			return nil, status.Error(codes.FailedPrecondition, lastInstanceAdminMessage)
		}
		return nil, convertUserWriteError(err, "failed to update user")
	}
	if passwordChanged {
		// A new password ends every other session. The caller's own browser
		// session survives when they changed their own password; an admin
		// resetting another account revokes all of that account's sessions.
		keepTokenID := ""
		if currentUser.ID == user.ID {
			keepTokenID = currentRefreshTokenID(ctx, s.Secret)
		}
		if err := s.Store.RemoveUserRefreshTokensExcept(ctx, user.ID, keepTokenID); err != nil {
			slog.Warn("failed to revoke sessions after password change", "user_id", user.ID, "error", err)
		}
	}

	return convertUserFromStore(updatedUser, currentUser), nil
}

func (s *APIService) DeleteUser(ctx context.Context, request *apipb.DeleteUserRequest) (*emptypb.Empty, error) {
	user, err := ResolveUserByName(ctx, s.Store, request.Name)
	if err != nil {
		return nil, status.Errorf(codes.InvalidArgument, "invalid user name: %v", err)
	}
	if user == nil {
		return nil, status.Errorf(codes.NotFound, "user not found")
	}
	userID := user.ID
	currentUser, err := s.fetchCurrentUser(ctx)
	if err != nil {
		return nil, status.Errorf(codes.Internal, "failed to get user: %v", err)
	}
	if currentUser == nil {
		return nil, status.Errorf(codes.Unauthenticated, "user not authenticated")
	}
	if currentUser.ID != userID && currentUser.Role != store.RoleAdmin {
		return nil, status.Errorf(codes.PermissionDenied, "permission denied")
	}
	isSelfDelete := currentUser.ID == userID

	deleteResult, err := s.Store.DeleteUser(ctx, &store.DeleteUser{
		ID: user.ID,
	})
	if err != nil {
		if stderrors.Is(err, store.ErrUserHasSpaceMembership) {
			return nil, status.Error(codes.FailedPrecondition, "leave all spaces before deleting this account")
		}
		if stderrors.Is(err, store.ErrLastInstanceAdmin) {
			return nil, status.Error(codes.FailedPrecondition, lastInstanceAdminMessage)
		}
		return nil, status.Errorf(codes.Internal, "failed to delete user: %v", err)
	}
	if isSelfDelete {
		if err := s.clearAuthCookies(ctx); err != nil {
			slog.Warn("failed to clear auth cookies after self delete", "user_id", userID, "error", err)
		}
	}
	if err := s.cleanupDeletedAttachmentStorage(ctx, deleteResult.Attachments); err != nil {
		return nil, status.Errorf(codes.Internal, "user was deleted but attachment storage cleanup failed: %v", err)
	}

	return &emptypb.Empty{}, nil
}

func (s *APIService) GetUserUsage(ctx context.Context, request *apipb.GetUserUsageRequest) (*apipb.UserUsage, error) {
	parent, ok := strings.CutSuffix(request.Name, "/usage")
	if !ok {
		return nil, status.Errorf(codes.InvalidArgument, "invalid user usage name %q", request.Name)
	}
	currentUser, err := s.fetchCurrentUser(ctx)
	if err != nil {
		return nil, status.Errorf(codes.Internal, "failed to get current user: %v", err)
	}
	if currentUser == nil {
		return nil, status.Errorf(codes.Unauthenticated, "user not authenticated")
	}
	username, err := parseUsernameFromName(parent)
	if err != nil {
		return nil, status.Errorf(codes.InvalidArgument, "invalid user name: %v", err)
	}
	user, err := s.Store.GetUser(ctx, &store.FindUser{Username: &username})
	if err != nil {
		return nil, status.Errorf(codes.Internal, "failed to get user: %v", err)
	}
	if user == nil {
		if currentUser.Role != store.RoleAdmin {
			return nil, status.Errorf(codes.PermissionDenied, "permission denied")
		}
		return nil, status.Errorf(codes.NotFound, "user not found")
	}
	if user.ID != currentUser.ID && currentUser.Role != store.RoleAdmin {
		return nil, status.Errorf(codes.PermissionDenied, "permission denied")
	}

	usage, err := usagelimit.UsageFor(ctx, s.Store, user.ID)
	if err != nil {
		return nil, status.Errorf(codes.Internal, "failed to get usage: %v", err)
	}
	limits := &apipb.UserUsage_Limits{}
	if entry := usage.Limits.Entry; entry != nil {
		limits.MemoCount = entry.MemoCount
		limits.MemoContentBytes = entry.MemoContentBytes
		limits.StorageBytes = entry.StorageBytes
		limits.UploadBytes = entry.UploadBytes
	}
	return &apipb.UserUsage{
		Name:         BuildUserName(user.Username) + "/usage",
		MemoCount:    usage.MemoCount,
		StorageBytes: usage.StorageBytes,
		Limits:       limits,
		LimitIndex:   int32(usage.Limits.Index),
	}, nil
}

func (s *APIService) DeleteMemoReaction(ctx context.Context, request *apipb.DeleteMemoReactionRequest) (*emptypb.Empty, error) {
	user, err := s.fetchCurrentUser(ctx)
	if err != nil {
		return nil, status.Errorf(codes.Internal, "failed to get current user: %v", err)
	}
	if user == nil {
		return nil, status.Errorf(codes.Unauthenticated, "user not authenticated")
	}

	memoUID, reactionID, err := ExtractMemoReactionIDFromName(request.Name)
	if err != nil {
		return nil, status.Errorf(codes.InvalidArgument, "invalid reaction name: %v", err)
	}

	// Get reaction and check ownership.
	reaction, err := s.Store.GetReaction(ctx, &store.FindReaction{
		ID: &reactionID,
	})
	if err != nil {
		return nil, status.Errorf(codes.Internal, "failed to get reaction")
	}
	if reaction == nil {
		// Return permission denied to avoid revealing if reaction exists.
		return nil, status.Errorf(codes.PermissionDenied, "permission denied")
	}

	if reaction.CreatorID != user.ID && !access.IsInstanceAdmin(user) {
		return nil, status.Errorf(codes.PermissionDenied, "permission denied")
	}
	memo, err := s.Store.GetMemo(ctx, &store.FindMemo{ID: &reaction.MemoID})
	if err != nil {
		return nil, status.Errorf(codes.Internal, "failed to get memo")
	}
	if memo == nil || memo.UID != memoUID {
		return nil, status.Errorf(codes.PermissionDenied, "permission denied")
	}
	if err := s.Store.DeleteReaction(ctx, &store.DeleteReaction{
		ID:          &reactionID,
		MemoID:      &reaction.MemoID,
		ActorUserID: &user.ID,
		Policy:      reactionWritePolicy(user.ID),
	}); err != nil {
		return nil, mapReactionMutationError(err, "failed to delete reaction")
	}

	s.SSEHub.publishMemoChanged()

	return &emptypb.Empty{}, nil
}

